messages.content:
{
 "what_you_observe": [
  "Tuesday, February 2. Seven pm.",
  "Phil said in the lobby: Rita, Larry—see you at the party. I'm heading to Pittsburgh.",
  "Rita said in the lobby: Alma, your daughter wants your voice. Talk to her.",
  "Rita records Alma at the Rialto and puts her recording on the patch.",
  "Larry records Alma on his last charged take. The reel stays with him.",
  "You are now at Rialto.",
  "There is time for one evening visit. The ballroom lights are on and the station line is open."
 ],
 "your_own_memories": [
  {
   "what_you_did": "Larry records Alma on his last charged take. The reel stays with him.",
   "what_you_said": "I don't turn back to the lobby. But I say, low, to the nearest one of them, the one who's still holding a saucer: 'Rialto's closing. I'm going to get a shot before the lights go out. Be back for the party.' It's not a question. I'm already walking.",
   "your_intention": "Get to the Rialto before the doors lock. Set the camera on the tripod by the booth where Alma sits. Let her talk to the lens the way she'd talk to a projection window. One take. Then wrap the reel, tag it, and get it onto the regional line before the last train out. Pittsburgh by Thursday, maybe earlier if the line's running clean."
  }
 ],
 "who_you_are_with": "your present location",
 "physical_choices": {
  "deliver_reel": "Bring your recording to the station patch for Rita.",
  "screen_party": "Show the festival footage at the ballroom if you have it.",
  "go_home": "Clock off and go home."
 }
}
